from moler.cmd.unix.genericunix import GenericUnixCommand
from moler.exceptions import ParsingDone
import re


class DisableRndPortsCgi(GenericUnixCommand):
    """Command disableRndPorts_cgi."""

    def build_command_string(self):
        """
        Build command string from parameters passed to object.

        :return: String representation of command to send over connection to device.
        """
        cmd = '/opt/trs/www/html/protected/disableRndPorts.cgi'
        return cmd

    def on_new_line(self, line, is_full_line):
        """
        Put your parsing code here.

        :param line: Line to process, can be only part of line. New line chars are removed from line.
        :param is_full_line: True if line had new line chars, False otherwise
        :return: None
        """
        if is_full_line:
            try:
                self._parse_service(line)
            except ParsingDone:
                pass
        return super(DisableRndPortsCgi, self).on_new_line(line, is_full_line)

    # <p><h3>R&D Ports Service Disabled Successfully</h3>
    _re_service = re.compile(r"R&D\sPorts\sService\sDisabled\s(?P<VAL>\w+)")

    def _parse_service(self, line):
        if self._regex_helper.search_compiled(DisableRndPortsCgi._re_service, line):
            self.current_ret["SERVICE_STATUS"] = self._regex_helper.group('VAL')
            raise ParsingDone


